<div class="d-flex justify-content-between align-items-center mb-4"><h2>Messages</h2></div><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0 admin-table"><thead><tr><th>#</th><th>Name</th><th>Email</th><th>Phone</th><th>Message</th><th>Date</th></tr></thead><tbody><?php foreach($messages as $m): ?><tr><td><?= html_escape($m->id) ?></td><td><?= html_escape($m->name) ?></td><td><?= html_escape($m->email) ?></td><td><?= html_escape(isset($m->phone)?$m->phone:(isset($m->mobile)?$m->mobile:'')) ?></td><td><a href="<?= site_url('admin/messages/view/'.$m->id) ?>" class="btn btn-sm btn-outline-primary">View Message</a></td><td><?= html_escape(isset($m->submitted_at)?$m->submitted_at:(isset($m->created_at)?$m->created_at:'')) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
